(5266616, 766060, 36981, '<td valign="top">This was far &amp; away my favorite, and my only 10.  I hope you get the blue!  It''s a very creative &amp; beautiful image.</td>', 'This was far & away my favorite, and my only 10.  I hope you get the blue!  It''s a very creative & beautiful image.', '2009-02-20 17:52:42.000000', NULL, 1),
(5266639, 765496, 93756, '<td valign="top">Love the color of this and the scene. Great photo. The only nitpick that I have is the close cropping above the nearest camel''s hump. More of the sky would have framed him nicer.</td>', 'Love the color of this and the scene. Great photo. The only nitpick that I have is the close cropping above the nearest camel''s hump. More of the sky would have framed him nicer.', '2009-02-20 18:09:30.000000', NULL, 1),
