INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5270082, 764873, 100495, '<td valign="top">The foreground is a bit messy, particularly the car and the posts. The sky looks intense but doesn''t look natural.</td>', 'The foreground is a bit messy, particularly the car and the posts. The sky looks intense but doesn''t look natural.', '2009-02-23 07:14:18.000000', NULL, 1),
(5270083, 765755, 100495, '<td valign="top">Great idea but let down by the busy background. With a plain bg the yellow/white/blue colours would have been brilliant and strinkng.<br/> <br/>Could be a bit sharper too.</td>', 'Great idea but let down by the busy background. With a plain bg the yellow/white/blue colours would have been brilliant and strinkng. Could be a bit sharper too.', '2009-02-23 07:15:35.000000', NULL, 1),
(5270086, 765891, 100495, '<td valign="top">Not very interesting and I think it needs to be sharper.</td>', 'Not very interesting and I think it needs to be sharper.', '2009-02-23 07:15:40.000000', NULL, 1),
(5270087, 765794, 100495, '<td valign="top">Not very interesting and the tilt doesn''t add anything for me.</td>', 'Not very interesting and the tilt doesn''t add anything for me.', '2009-02-23 07:15:53.000000', NULL, 1),
(5270088, 765153, 100495, '<td valign="top">Beautiful animal in a rather uninspiring setting. I think the duck needs to be sharper.</td>', 'Beautiful animal in a rather uninspiring setting. I think the duck needs to be sharper.', '2009-02-23 07:15:59.000000', NULL, 1),
(5270089, 766318, 100495, '<td valign="top">The subject and lighting are a little dull and the hills make it hard to see what the horizon is doing.</td>', 'The subject and lighting are a little dull and the hills make it hard to see what the horizon is doing.', '2009-02-23 07:16:03.000000', NULL, 1),
(5270090, 765847, 100495, '<td valign="top">Quite an uninteresting image and I don''t think the tilt adds to it.</td>', 'Quite an uninteresting image and I don''t think the tilt adds to it.', '2009-02-23 07:16:06.000000', NULL, 1),
(5270091, 764789, 100495, '<td valign="top">excellent use of dead space. Is that horizon tilted?</td>', 'excellent use of dead space. Is that horizon tilted?', '2009-02-23 07:16:12.000000', NULL, 1),
(5270094, 765274, 100495, '<td valign="top">Too blurry. Good idea on the composition, but it doesn''t quite work.</td>', 'Too blurry. Good idea on the composition, but it doesn''t quite work.', '2009-02-23 07:17:25.000000', NULL, 1),
(5270123, 765884, 100318, '<td valign="top">I like the streaks in the sky. At first glance it looked like a ship - nice shot</td>', 'I like the streaks in the sky. At first glance it looked like a ship - nice shot', '2009-02-23 07:53:33.000000', NULL, 1),
(5270265, 765672, 104145, '<td valign="top">This works so well because it actually has a reason to be tilted.</td>', 'This works so well because it actually has a reason to be tilted.', '2009-02-23 09:30:35.000000', NULL, 1),
(5270268, 765659, 104145, '<td valign="top">Beautiful shot and very interesting, and fun!</td>', 'Beautiful shot and very interesting, and fun!', '2009-02-23 09:31:42.000000', NULL, 1),
(5270277, 765711, 104145, '<td valign="top">After looking at all the pictures I had to come back to your because it was memorable, unique and funny. There is also a reason and purpose to tilt the picture. It would in my opinion be less of a picture if it wasn''t tilted. A+++++. This coming from an amateur photographer.</td>', 'After looking at all the pictures I had to come back to your because it was memorable, unique and funny. There is also a reason and purpose to tilt the picture. It would in my opinion be less of a picture if it wasn''t tilted. A+++++. This coming from an amateur photographer.', '2009-02-23 09:35:57.000000', NULL, 1),
(5270390, 765366, 57447, '<td valign="top">Superb..wow</td>', 'Superb..wow', '2009-02-23 10:46:36.000000', NULL, 1),
(5270469, 764887, 103563, '<td valign="top">I love this picture. The picture looks really soft and smooth and you met the challenge well</td>', 'I love this picture. The picture looks really soft and smooth and you met the challenge well', '2009-02-23 11:48:20.000000', NULL, 1),
(5271101, 766189, 96831, '<td valign="top">Decent concept, but in my opinion, it would have been more effective without the tree in the shot.</td>', 'Decent concept, but in my opinion, it would have been more effective without the tree in the shot.', '2009-02-23 17:24:12.000000', NULL, 1),
(5271268, 765772, 103922, '<td valign="top">Where is the horizon?</td>', 'Where is the horizon?', '2009-02-23 19:19:40.000000', NULL, 1),
(5271437, 766133, 82749, '<td valign="top">Very nice perspective.</td>', 'Very nice perspective.', '2009-02-23 21:08:53.000000', NULL, 1),
(5271609, 765800, 79955, '<td valign="top">Lighting harsh on the couple. Wish you had used some fill flash to lighten the shadows on the couple. 6</td>', 'Lighting harsh on the couple. Wish you had used some fill flash to lighten the shadows on the couple. 6', '2009-02-23 22:46:35.000000', NULL, 1),
(5271684, 765091, 63633, '<td valign="top">I really love this. The subdued tones are lovely and the tilt is really effective.</td>', 'I really love this. The subdued tones are lovely and the tilt is really effective.', '2009-02-24 00:26:15.000000', NULL, 1),
(5271685, 766103, 63633, '<td valign="top">Beautiful image. The tilt really adds to the image and the white and blue look lovely together.</td>', 'Beautiful image. The tilt really adds to the image and the white and blue look lovely together.', '2009-02-24 00:27:13.000000', NULL, 1),
(5271686, 766176, 63633, '<td valign="top">A very original entry. I hope it does well for you - 7</td>', 'A very original entry. I hope it does well for you - 7', '2009-02-24 00:27:54.000000', NULL, 1),
(5271696, 765659, 102505, '<td valign="top">''effing brilliant 7</td>', '''effing brilliant 7', '2009-02-24 00:51:47.000000', NULL, 1),
(5271699, 766276, 102505, '<td valign="top">At the risk of sounding like a pompous ass (I might be one anyway) if your still working with a point and shoot You''ve simply outgrown your camera. I would love to see what kind of results you might give us with a tripod and more control over your shutter speed.<br/>If your on a DSLR, take your time and learn to work your camera. Find out what shutter speeds you need at what light to keep the ISO noise out of your picture. <br/>Get the most out of your camera and your pictures.</td>', 'At the risk of sounding like a pompous ass (I might be one anyway) if your still working with a point and shoot You''ve simply outgrown your camera. I would love to see what kind of results you might give us with a tripod and more control over your shutter speed.If your on a DSLR, take your time and learn to work your camera. Find out what shutter speeds you need at what light to keep the ISO noise out of your picture. Get the most out of your camera and your pictures.', '2009-02-24 00:59:55.000000', NULL, 1),
