(5272772, 765189, 86447, '<td valign="top">LOL!   I wish I could see his face.  Really cute idea.</td>', 'LOL!   I wish I could see his face.  Really cute idea.', '2009-02-24 20:29:59.000000', NULL, 1),
(5272802, 766194, 32872, '<td valign="top">I love your use of tilting! :)<br/> <br/>It works so well in this nicely-executed image.  Aptly titled, too!</td>', 'I love your use of tilting! :) It works so well in this nicely-executed image.  Aptly titled, too!', '2009-02-24 20:57:07.000000', NULL, 1),
