(5273985, 766119, 72670, '<td valign="top">Johnathan <br/>Good on ya. This is a good example of two  pics not suffering from being of the same subject. Your team is off to a good start!</td>', 'Johnathan Good on ya. This is a good example of two  pics not suffering from being of the same subject. Your team is off to a good start!', '2009-02-25 08:40:21.000000', NULL, 0),
(5273989, 765096, 84438, '<td valign="top">Definitely should have scored higher.  Good photo!</td>', 'Definitely should have scored higher.  Good photo!', '2009-02-25 08:45:00.000000', NULL, 0),
(5274010, 766252, 67697, '<td valign="top">Not a day for diagonals I guess.  I like how there''s some tracks in the foreground acting as a parallel to the horizon.  The clouds are my fave part - beautiful!</td>', 'Not a day for diagonals I guess.  I like how there''s some tracks in the foreground acting as a parallel to the horizon.  The clouds are my fave part - beautiful!', '2009-02-25 08:53:35.000000', NULL, 0),
(5274015, 764887, 67697, '<td valign="top">See, I knew the voters would like it.  I do like that the one in the background creates the balance in the scene.  Congrats on a 6+!</td>', 'See, I knew the voters would like it.  I do like that the one in the background creates the balance in the scene.  Congrats on a 6+!', '2009-02-25 08:56:06.000000', NULL, 0),
(5274017, 765840, 58457, '<td valign="top">the out of focus birds really help this shot.  I don''t think I would''ve stopped to take a picture of that feather.  I''ll think again after seeing this.  so much stronger than the cliche sunsets we see here.</td>', 'the out of focus birds really help this shot.  I don''t think I would''ve stopped to take a picture of that feather.  I''ll think again after seeing this.  so much stronger than the cliche sunsets we see here.', '2009-02-25 08:58:05.000000', NULL, 0),
(5274023, 765659, 58457, '<td valign="top">those people who said you didn''t have a tilted horizon can stuff it!  you did!  you just straightened it!  The white on white on white really brings out the contrast of the glass.  Well played.</td>', 'those people who said you didn''t have a tilted horizon can stuff it!  you did!  you just straightened it!  The white on white on white really brings out the contrast of the glass.  Well played.', '2009-02-25 09:00:15.000000', NULL, 0),
(5274027, 765704, 45631, '<td valign="top">Absolutely love this shot Lonnie.  Congratulations on your first ribbon.  <br/><br/><br/><i>Message edited by author 2009-02-25 09:17:05.</i></td>', 'Absolutely love this shot Lonnie.  Congratulations on your first ribbon.  ', '2009-02-25 09:02:43.000000', '2009-02-25 09:17:05.000000', 0),
(5274033, 764892, 67697, '<td valign="top">Interesting that you have used the ball of light to represent the bundle of energy that is probably resting in that stroller :)</td>', 'Interesting that you have used the ball of light to represent the bundle of energy that is probably resting in that stroller :)', '2009-02-25 09:06:37.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
